#!/bin/bash
: > raw.jsonl
D30=$(date -u -d '30 days ago' +%F); D90=$(date -u -d '90 days ago' +%F)
F=fullName,stargazersCount,forksCount,description,createdAt,pushedAt,language
run(){ n=$1; shift; gh search repos "$@" --limit $n --json $F >> raw.jsonl 2>/dev/null; echo >> raw.jsonl; sleep 3; }
for t in claude-skills agent-skills claude-code-skills skills-sh claude-skill agent-skill skill-md codex-skills openclaw-skills ai-skills; do run 300 --topic "$t" --sort stars; run 100 --topic "$t" --sort stars --created ">$D90"; done
for q in "claude skills" "agent skills" "claude code skills" "SKILL.md" "awesome skills" "codex skills" "openclaw skills" "claude skill" "agent skill" "skills for claude" "ai agent skills" "技能 claude" "skill 技能包"; do run 200 "$q" --sort stars; run 100 "$q" --sort stars --created ">$D30"; run 100 "$q" --sort stars --created ">$D90"; done
for q in "ecommerce skills" "电商 skill" "amazon skills" "shopify skills" "xiaohongshu skill" "小红书 skill" "douyin skill" "抖音 skill" "tiktok skills" "公众号 skill" "seo skills" "marketing skills" "sales skills agent" "video skill claude" "视频 skill" "design skills agent" "ppt skill" "image skill claude" "writing skills claude" "写作 skill" "translation skill claude" "office skills claude" "excel skill claude" "pdf skill claude" "notion skill" "obsidian skills" "finance skills claude" "trading skill claude" "股票 skill" "legal skills claude" "法律 skill" "medical skills claude" "health skill claude" "education skills claude" "学习 skill" "research skills claude" "scientific skills claude" "论文 skill" "data analysis skills claude" "product manager skills" "security skills claude" "devops skills claude" "frontend skills claude" "game skills claude" "automation skills agent" "browser skill claude" "productivity skills claude" "career skill claude" "简历 skill" "customer support skills agent" "hr skills claude" "travel skill claude" "cooking skill claude" "music skill claude" "3d skill claude" "math skill claude" "prompt skills claude" "mcp skills"; do run 100 "$q" --sort stars; done
grep -c '^\[' raw.jsonl
